@contextmanager
def lock(folder):
    folder = Path(folder).resolve()
    folder.mkdir(parents=True, exist_ok=True)
    path = folder / ".lock"
    try:
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    except (FileExistsError, PermissionError) as error:
        if not isinstance(error, FileExistsError):
            # Windows reports an existing directory at .lock as permission
            # denied. Preserve ordinary access errors when no lock is observed.
            try:
                path.lstat()
            except OSError:
                raise error
        observation = _lock_observation(path)
        owner = observation.get("owner", {})
        detail = f"{path}; owner metadata {observation['metadata_status']}"
        if owner:
            detail += f"; recorded PID {owner['pid']}"
            if "host" in owner:
                detail += f" on host {owner['host']!r}"
            if "acquired_at" in owner:
                detail += f"; acquired_at {owner['acquired_at']}"
        raise PixlError(
            "store_locked",
            detail + "; owner liveness is unverified. Keep this lock until all writers are confirmed stopped; PID or age alone is not proof of an abandoned lock.",
            context={"lock": observation},
        ) from error
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            metadata = {"pid": os.getpid(), "acquired_at": datetime.now(UTC).isoformat()}
            try:
                metadata["host"] = socket.gethostname()
            except OSError:
                pass
            json.dump(metadata, stream)
            stream.flush()
            os.fsync(stream.fileno())
        yield
    finally:
        path.unlink(missing_ok=True)


def _atomic(path, data):
    path = Path(path)
    fd, temp = tempfile.mkstemp(prefix=".pixl-write-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
    finally:
        Path(temp).unlink(missing_ok=True)


def _publish(folder: Path, doc: Document) -> PublicationResult:
    data, hash_ = encode(doc), digest(doc)
    history = folder / "history"
    if history.is_symlink() or not history.resolve().is_relative_to(folder):
        raise PixlError("store_path", "history must remain inside the store")
    history.mkdir(exist_ok=True)
    snapshot = history / f"{hash_}.px"
    if snapshot.is_symlink() or not snapshot.resolve().is_relative_to(folder):
        raise PixlError("store_path", "snapshot must remain inside the store")
    if snapshot.exists():
        if snapshot.read_bytes() != data:
            raise PixlError("history_corrupt", str(snapshot))
    else:
        _atomic(snapshot, data)
    _atomic(folder / "state.px", data)
    return {"revision": doc.revision, "hash": hash_, "state": str(folder / "state.px")}


